<script setup>
import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import AlbumArtwork from'../../components/AlbumArtwork.vue';import{consoleApi}from'../../api/console';
const loading=ref(false),saving=ref(false),rows=ref([]),total=ref(0),pageSize=ref(10),dialog=ref(false),detailOpen=ref(false),detail=ref({});const query=reactive({page:1,musicName:'',typeName:'',tagName:''});const form=reactive({id:null,coverImages:'',musicName:'',singerName:'',albumTitle:'',releaseDate:'',musicDesc:'',typeId:null,tags:''});
async function load(){loading.value=true;try{const{result}=await consoleApi.musicList(query);rows.value=result.list||[];total.value=result.total||0;pageSize.value=result.pageSize||10}catch(error){ElMessage.error(error?.message||'音乐列表加载失败')}finally{loading.value=false}}
function openCreate(){Object.assign(form,{id:null,coverImages:'',musicName:'',singerName:'',albumTitle:'',releaseDate:'',musicDesc:'',typeId:null,tags:''});dialog.value=true}
async function openEdit(row){try{const{result}=await consoleApi.musicInfo(row.id);Object.assign(form,{id:row.id,coverImages:(result.coverImages||[]).join('$'),musicName:result.musicName||'',singerName:result.singerName||'',albumTitle:result.albumTitle||'',releaseDate:result.releaseDate||'',musicDesc:result.musicDesc||'',typeId:result.typeId??null,tags:(result.tags||[]).join('$')});dialog.value=true}catch(error){ElMessage.error(error?.message||'音乐详情加载失败')}}
async function showDetail(row){try{detail.value=(await consoleApi.musicInfo(row.id)).result;detailOpen.value=true}catch(error){ElMessage.error(error?.message||'音乐详情加载失败')}}
async function save(){if(!String(form.musicName||'').trim())return ElMessage.warning('请输入歌曲名称');if(!String(form.singerName||'').trim())return ElMessage.warning('请输入音乐人');if(!form.id&&!String(form.coverImages||'').trim())return ElMessage.warning('请输入封面 URL');saving.value=true;try{await consoleApi.saveMusic(form);ElMessage.success(form.id?'音乐已更新':'音乐已创建');dialog.value=false;await load()}catch(error){ElMessage.error(error?.message||'音乐保存失败')}finally{saving.value=false}}
async function remove(row){try{await ElMessageBox.confirm(`确认删除《${row.musicName}》？此操作不可撤销。`,'删除音乐',{type:'warning'});await consoleApi.deleteMusic(row.id);ElMessage.success('音乐已删除');await load()}catch(error){if(error!=='cancel'&&error!=='close')ElMessage.error(error?.message||'音乐删除失败')}}
onMounted(load)
</script>
<template><div><div class="top"><div><span class="eyebrow">CONTENT LIBRARY / MUSIC</span><h1 class="page-title">音乐内容</h1><p>维护卡片内容、分类关联与批量数据。</p></div><div class="top-actions"><el-button>⇩ 导出 Excel</el-button><el-button>⇧ 批量导入</el-button><el-button type="primary" @click="openCreate">＋ 新增音乐</el-button></div></div><section class="filters"><el-input v-model="query.musicName" placeholder="搜索歌曲名称" clearable @keyup.enter="query.page=1;load()"/><el-input v-model="query.typeName" placeholder="分类名称" clearable/><el-input v-model="query.tagName" placeholder="标签名称" clearable/><el-button type="primary" @click="query.page=1;load()">筛选内容</el-button><el-button @click="Object.assign(query,{page:1,musicName:'',typeName:'',tagName:''});load()">重置</el-button></section><section class="table-panel"><div class="table-meta"><span>内容资产 <b>{{total}}</b></span><small>数据源 / MUSIC SERVICE</small></div><el-table :data="rows" v-loading="loading" style="width:100%"><el-table-column width="76" label="封面"><template #default="{row}"><AlbumArtwork :item="row"/></template></el-table-column><el-table-column prop="musicName" label="音乐"><template #default="{row}"><button class="name" @click="showDetail(row)">{{row.musicName}}<small>ID {{row.id}}</small></button></template></el-table-column><el-table-column prop="singerName" label="音乐人" min-width="120"/><el-table-column prop="typeName" label="分类"><template #default="{row}"><el-tag effect="plain" round>{{row.typeName}}</el-tag></template></el-table-column><el-table-column prop="musicDesc" label="描述" min-width="220" show-overflow-tooltip/><el-table-column fixed="right" label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><div class="pagination"><span>每页 {{pageSize}} 条</span><el-pagination v-model:current-page="query.page" layout="prev,pager,next" :page-size="pageSize" :total="total" @current-change="load"/></div></section><el-dialog v-model="dialog" :title="form.id?'编辑音乐':'创建音乐'" width="min(680px,92vw)"><el-form label-position="top"><div class="form-grid"><el-form-item label="歌曲名称"><el-input v-model="form.musicName"/></el-form-item><el-form-item label="音乐人"><el-input v-model="form.singerName"/></el-form-item><el-form-item label="专辑名称"><el-input v-model="form.albumTitle"/></el-form-item><el-form-item label="发行日期"><el-input v-model="form.releaseDate" placeholder="yyyy-MM-dd"/></el-form-item><el-form-item label="分类 ID"><el-input-number v-model="form.typeId" :min="1" controls-position="right"/></el-form-item><el-form-item label="标签"><el-input v-model="form.tags" placeholder="多个标签以 $ 分隔"/></el-form-item></div><el-form-item label="封面 URL"><el-input v-model="form.coverImages" placeholder="多张封面以 $ 分隔"/></el-form-item><el-form-item label="音乐介绍"><el-input v-model="form.musicDesc" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存内容</el-button></template></el-dialog><el-drawer v-model="detailOpen" title="音乐档案" size="min(480px,92vw)"><AlbumArtwork :item="detail"/><h2>{{detail.musicName}}</h2><p class="drawer-artist">{{detail.singerName}} · {{detail.typeName}}</p><p>{{detail.musicDesc}}</p><el-descriptions :column="1" border><el-descriptions-item label="专辑">{{detail.albumTitle}}</el-descriptions-item><el-descriptions-item label="发行">{{detail.releaseDate}}</el-descriptions-item><el-descriptions-item label="标签">{{detail.tags?.join(' / ')}}</el-descriptions-item><el-descriptions-item label="更新">{{detail.updateTime}}</el-descriptions-item></el-descriptions></el-drawer></div></template>
<style scoped>.top{display:flex;justify-content:space-between;align-items:end;margin-bottom:28px}.top p{color:var(--muted);margin:10px 0 0}.top-actions{display:flex;gap:8px}.filters{display:grid;grid-template-columns:1.3fr 1fr 1fr auto auto;gap:10px;padding:16px;margin-bottom:16px;background:#fff;border:1px solid var(--line);border-radius:18px}.table-panel{padding:18px;background:#fff;border:1px solid var(--line);border-radius:20px}.table-meta{display:flex;justify-content:space-between;padding:4px 4px 16px;font-size:12px}.table-meta b{color:var(--violet)}.table-meta small{font:8px var(--mono);color:var(--muted)}.table-panel :deep(.art){width:48px;min-height:48px;border-radius:10px}.name{border:0;background:none;text-align:left;font-weight:700;cursor:pointer}.name small{display:block;margin-top:3px;font:8px var(--mono);color:var(--muted)}.pagination{display:flex;justify-content:space-between;align-items:center;padding-top:18px;color:var(--muted);font-size:10px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.drawer-artist{color:var(--violet);font-weight:700}@media(max-width:900px){.top{align-items:start}.top-actions{display:grid}.filters{grid-template-columns:1fr 1fr}.filters .el-input:first-child{grid-column:span 2}}@media(max-width:600px){.top{display:block}.top-actions{grid-template-columns:1fr 1fr;margin-top:20px}.top-actions .el-button{margin:0}.filters{grid-template-columns:1fr}.filters .el-input:first-child{grid-column:auto}.form-grid{grid-template-columns:1fr}.table-panel{padding:10px}.top-actions .el-button:first-child{display:none}}</style>
<style scoped>.form-grid :deep(.el-form-item:nth-child(1) .el-form-item__label:before),.form-grid :deep(.el-form-item:nth-child(2) .el-form-item__label:before),.el-dialog :deep(.el-form>.el-form-item:nth-last-child(2) .el-form-item__label:before){content:'*';color:#ff6f91;margin-right:4px}</style>
